def dedupe_recipient_emails(apps, schema_editor):
    """Collapse historical (campaign, email) duplicates before re-indexing.

    The old constraint keyed on (campaign, user), so two accounts sharing one
    mailbox produced duplicate rows. The new dedupe constraint needs one row
    per address: keep the most-successful outcome (a sent copy outranks a
    failed duplicate) and drop the rest.
    """
    Row = apps.get_model('learning', 'EmailCampaignRecipient')
    rank = {'sent': 0, 'render_only': 1, 'pending': 2, 'skipped': 3, 'failed': 4}
    survivors = {}
    duplicates = []
    for row in Row.objects.order_by('campaign_id', 'email', 'id').only('id', 'campaign_id', 'email', 'status'):
        key = (row.campaign_id, row.email.lower())
        if key not in survivors:
            survivors[key] = row
            continue
        if rank.get(row.status, 9) < rank.get(survivors[key].status, 9):
            duplicates.append(survivors[key])
            survivors[key] = row
        else:
            duplicates.append(row)
    for row in duplicates:
        row.delete()


